package com.watchalign.mobile;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class LuminousPartialFitTest {
 static double[][] edge(double[][] vertices,boolean[] included){List<double[]> p=new ArrayList<>();for(int i=0;i<vertices.length;i++)if(included[i]){double[] a=vertices[i],b=vertices[(i+1)%vertices.length];for(int k=3;k<38;k++){double t=k/40.0;p.add(new double[]{a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])});}}return p.toArray(new double[0][]);}
 @Test public void triangleWithUnobservedCornersFitsIndependentSides(){double[][] truth={{0,.08},{-.05,-.06},{.05,-.06}};double[][] p=edge(truth,new boolean[]{true,true,true});LuminousPartialFit.Fit f=LuminousPartialFit.fit(p,ModelSpec.Shape.TRIANGLE,12,500);assertNotNull(f.ideal);assertNotNull(f.center);assertEquals(0,f.center[0],1e-7);assertEquals(-.01333333333,f.center[1],1e-6);assertTrue(f.orientation);assertEquals(.1,f.width,1e-5);assertEquals(.14,f.height,1e-5);}
 @Test public void twoTriangleSidesDoNotInventBaseCentreOrCompleteArea(){double[][] truth={{0,.08},{-.05,-.06},{.05,-.06}};LuminousPartialFit.Fit f=LuminousPartialFit.fit(edge(truth,new boolean[]{true,false,true}),ModelSpec.Shape.TRIANGLE,12,500);assertTrue(f.orientation);assertNull(f.center);assertNull(f.ideal);assertTrue(Double.isNaN(f.width));}
 @Test public void batonLongEdgesPreserveDirectionAndWidthWithoutInventingEnds(){double[][] truth={{-.025,-.10},{.025,-.10},{.025,.10},{-.025,.10}};LuminousPartialFit.Fit f=LuminousPartialFit.fit(edge(truth,new boolean[]{false,true,false,true}),ModelSpec.Shape.BATON,12,500);assertTrue(f.orientation);assertEquals(.05,f.width,1e-5);assertNull(f.center);assertNull(f.ideal);assertTrue(Double.isNaN(f.height));assertTrue(Double.isFinite(f.crossC));}
 @Test public void oneBatonEdgeDoesNotInventWidth(){double[][] truth={{-.025,-.10},{.025,-.10},{.025,.10},{-.025,.10}};LuminousPartialFit.Fit f=LuminousPartialFit.fit(edge(truth,new boolean[]{false,true,false,false}),ModelSpec.Shape.BATON,12,500);assertTrue(f.orientation);assertTrue(Double.isNaN(f.width));assertNull(f.center);}
 @Test public void distributedArcsFitFreeCentreAndRadiusWithOutliers(){List<double[]> p=new ArrayList<>();for(int k=0;k<96;k++){double a=k*2*Math.PI/96;if(a>.2&&a<1.1)continue;p.add(new double[]{.01+.045*Math.cos(a),-.02+.045*Math.sin(a)});}p.add(new double[]{.09,.07});p.add(new double[]{-.12,.02});LuminousPartialFit.Fit f=LuminousPartialFit.fit(p.toArray(new double[0][]),ModelSpec.Shape.ROUND,12,500);assertNotNull(f.center);assertArrayEquals(new double[]{.01,-.02},f.center,1e-6);assertEquals(.045,f.radius,1e-6);assertFalse(f.orientation);}
 @Test public void shortArcDoesNotClaimCircleCentre(){List<double[]> p=new ArrayList<>();for(int k=0;k<50;k++){double a=k*.01;p.add(new double[]{.04*Math.cos(a),.04*Math.sin(a)});}LuminousPartialFit.Fit f=LuminousPartialFit.fit(p.toArray(new double[0][]),ModelSpec.Shape.ROUND,12,500);assertNull(f.center);assertTrue(Double.isNaN(f.radius));}
 @Test public void fourIndependentEdgesReconstructSkewWithoutForcingParallelSides(){double[][] q={{-.03,-.1},{.03,-.1},{.015,.1},{-.02,.1}};LuminousPartialFit.Fit f=LuminousPartialFit.fit(edge(q,new boolean[]{true,true,true,true}),ModelSpec.Shape.BATON,12,500);assertNotNull(f.ideal);assertNotNull(f.center);assertEquals(MarkerPolygonMismatch.area(q),MarkerPolygonMismatch.area(f.ideal),1e-6);}
 @Test public void alignmentOnlyRetainsReferenceSizeWhileFittedSizeChangesArea(){double[][] expected=MarkerPolygonMismatch.circle(.1,-.7,.04,128);ModelSpec.Marker spec=new ModelSpec.Marker(12,ModelSpec.Shape.ROUND,"rounds",.7,.06,0,0,0,0,0,0,0);LuminousMarkerDetector.Detection d=new LuminousMarkerDetector.Detection(12);d.alignment=LuminousPartialFit.fit(MarkerPolygonMismatch.circle(.1,-.7,.05,96),ModelSpec.Shape.ROUND,12,500);LuminousMeasurement.Marker m=new LuminousMeasurement.Marker(spec,d,expected);assertNotNull(m.fittedScore);assertNotNull(m.alignmentScore);assertTrue(m.fittedScore.mismatchPct>50);assertTrue(m.alignmentScore.mismatchPct<1e-7);assertNull(m.score);assertEquals(m.alignmentScore.expectedArea,m.alignmentScore.actualArea,1e-10);}
 @Test public void rigidAlignmentTransformPreservesAreaAndInput(){double[][] e={{0,0},{2,0},{2,1},{0,1}},snapshot=MarkerPolygonMismatch.copyPolygon(e);double[][] a=LuminousMeasurement.rigid(e,new double[]{1,.5},new double[]{1.2,.7},.1);assertEquals(MarkerPolygonMismatch.area(e),MarkerPolygonMismatch.area(a),1e-12);for(int i=0;i<e.length;i++)assertArrayEquals(snapshot[i],e[i],0);MarkerPolygonMismatch.Score s=MarkerPolygonMismatch.compare(e,a);assertTrue(s.mismatchPct>0);assertEquals(s.extraPct+s.missingPct,s.mismatchPct,1e-12);}
 @Test public void eachFittedRegionMatchesItsOwnPolygonArea(){double[][] e={{-.02,-.10},{.02,-.10},{.02,.10},{-.02,.10}};MarkerPolygonMismatch.Score s=MarkerPolygonMismatch.compare(e,LuminousMeasurement.rigid(e,new double[]{0,0},new double[]{.002,.003},.05));assertEquals(s.extraArea,s.extraRegions().stream().mapToDouble(MarkerPolygonMismatch::area).sum(),1e-10);assertEquals(s.missingArea,s.missingRegions().stream().mapToDouble(MarkerPolygonMismatch::area).sum(),1e-10);}
}
